}
const data = bad.map(({ r, reason }) => { const p = Object.assign({}, r.post, { status: 'failed', error: reason }); return botWrite(r.sheetRow, p); });
const out = { pick: false, fix: bad.length > 0, fix_http: bad.length ? batchUpdate(data) : null, chat: cfg.approval_chat_id,
  fix_text: bad.length ? ['Строки плана, которые бот не может взять:', ...bad.map(({ r, reason }) => `• строка ${r.sheetRow} «${r.post.topic.slice(0, 80)}» — ${reason}`)].join('\n') : '' };
