ready.sort((a, b) => a.at - b.at);
const { r } = ready[0];
const p = r.post;
const ch = cfg.channels[p.channel];
const id = p.id || `${stamp(now).replace(/[-: ]/g, '').slice(2)}-${r.sheetRow}`;
